import numpy as np
from PIL import Image
im=np.array(Image.open('first_frame.png').convert('RGB'))
# inspect all strong neutral-bright points around row sorted by x,y
for y in range(88,106):
 xs=[]
 for x in range(120,176):
  rgb=im[y,x].astype(float); sat=rgb.max()-rgb.min(); lum=.299*rgb[0]+.587*rgb[1]+.114*rgb[2]
  if sat<16 and lum>135:xs.append(x)
 if xs:print(y,xs)
